CREATE TYPE "AmenityBookingStatus" AS ENUM ('PENDING', 'CONFIRMED', 'CANCELLED');
CREATE TABLE "Amenity" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "location" TEXT, "capacity" INTEGER NOT NULL DEFAULT 10, "imageUrl" TEXT, "isActive" BOOLEAN NOT NULL DEFAULT true, "operatingHours" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Amenity_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AmenityBooking" ("id" TEXT NOT NULL, "amenityId" TEXT NOT NULL, "residentId" TEXT NOT NULL, "unitId" TEXT, "date" TEXT NOT NULL, "startTime" TEXT NOT NULL, "endTime" TEXT NOT NULL, "status" "AmenityBookingStatus" NOT NULL DEFAULT 'PENDING', "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AmenityBooking_pkey" PRIMARY KEY ("id"));
ALTER TABLE "AmenityBooking" ADD CONSTRAINT "AmenityBooking_amenityId_fkey" FOREIGN KEY ("amenityId") REFERENCES "Amenity"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "AmenityBooking" ADD CONSTRAINT "AmenityBooking_residentId_fkey" FOREIGN KEY ("residentId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "AmenityBooking" ADD CONSTRAINT "AmenityBooking_unitId_fkey" FOREIGN KEY ("unitId") REFERENCES "Unit"("id") ON DELETE SET NULL ON UPDATE CASCADE;
